{
  "name": "getAttachmentFile",
  "type": "function",
  "description": "Gets the content of a $(ref:messages.MessageAttachment) as a $(url:dom-file)[File] object. If the message is encrypted, the function retrieves the attachment from the decrypted message.",
  "async": "callback",
  "parameters": [
    {
      "name": "messageId",
      "$ref": "messages.MessageId"
    },
    {
      "name": "partName",
      "description": "The <var>partName</var> of an attachment to be retrieved from the decrypted message.",
      "type": "string",
      "pattern": "^\\d+(\\.\\d+\\$?)*$"
    },
    {
      "type": "function",
      "name": "callback",
      "optional": true,
      "parameters": [
        {
          "type": "object",
          "isInstanceOf": "File",
          "additionalProperties": true
        }
